function journaliser(req, res, next) {
  const debut = Date.now();

  res.on("finish", () => {
    console.log(req.method, req.originalUrl, res.statusCode, `${Date.now() - debut}ms`);
  });

  next();
}

app.use(journaliser);

app.use(express.json({ limit: "100kb" }));

app.post("/api/utilisateurs", (req, res) => {
  const { nom, email } = req.body;

  if (typeof nom !== "string" || typeof email !== "string") {
    return res.status(400).json({ erreur: "nom et email sont requis" });
  }

  return res.status(201).json({ nom, email });
});

