const notes = [];

app.post("/api/notes", (req, res) => {
  if (typeof req.body.titre !== "string" || !req.body.titre.trim()) {
    return res.status(400).json({ erreur: "titre requis" });
  }
  const note = { id: notes.length + 1, titre: req.body.titre.trim() };
  notes.push(note);
  res.status(201).json(note);
});

app.use((erreur, req, res, next) => {
  console.error(erreur);

  if (res.headersSent) {
    return next(erreur);
  }

  return res.status(500).json({
    erreur: "Une erreur interne est survenue"
  });
});

