import { useEffect } from "react";

function Statut({ canal }) {
  useEffect(() => {
    const connexion = connecter(canal);
    connexion.ouvrir();

    return () => connexion.fermer();
  }, [canal]);

  return <p>Canal : {canal}</p>;
}

