export async function POST(request: Request) {
  let corps: unknown;
  try { corps = await request.json(); }
  catch { return Response.json({ erreur: "JSON invalide" }, { status: 400 }); }
  if (typeof corps !== "object" || corps === null || !("titre" in corps) ||
      typeof corps.titre !== "string" || !corps.titre.trim() || corps.titre.length > 80) {
    return Response.json({ erreur: "titre invalide" }, { status: 400 });
  }
  return Response.json({ titre: corps.titre.trim() }, { status: 201 });
}

type Resultat<T> = { ok: true; valeur: T } | { ok: false; erreur: string };
function lireAge(texte: string): Resultat<number> {
  const age = Number(texte);
  if (!Number.isInteger(age) || age < 0 || texte.trim() === "")
    return { ok: false, erreur: "âge invalide" };
  return { ok: true, valeur: age };
}
const resultat = lireAge("18");
console.log(resultat.ok ? resultat.valeur + 1 : resultat.erreur);

